using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "OnShuffleDicePoolOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/OnShuffleDicePoolOmenData")]
public class OnShuffleDicePoolOmenData : OmenData
{
	[NonSerialized]
	private Action omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate
		{
			omenInstance.ActivateOmenFeedback();
			ActivateOmen();
		};
		ReferenceSingleton<MiscOmensHandler>.Instance.OnShuffleDicePoolOmenActions.Add(omenAction);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.OnShuffleDicePoolOmenActions.Add(omenAction);
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(base.localizationManager.GetWheneverYouShuffleYourDicePool(), BattleAction.GetActionDescription(ActionValue).LowercaseFirst());
	}
}
